mapper.select:
SELECT

FROM outbox_event
WHERE source = #{source}
  AND event_id = #{eventId}
LIMIT 1

SELECT

FROM outbox_event
WHERE status = 'PENDING'
   OR (
       status = 'PROCESSING'
       AND lease_until <= #{now}
   )
ORDER BY created_at ASC
LIMIT #{limit}

mapper.update:
UPDATE outbox_event
SET
    retry_count = retry_count + 1,
    last_error = #{lastError}
WHERE id = #{id}
  AND status = 'PROCESSING'
  AND lease_owner = #{leaseOwner}

UPDATE outbox_event
SET
    status = 'PROCESSING',
    lease_owner = #{leaseOwner},
    lease_until = #{leaseUntil}
WHERE id = #{id}
  AND (
      status = 'PENDING'
      OR (
          status = 'PROCESSING'
          AND lease_until <= #{now}
      )
  )
